const recurringHolidays = [
  { date: '0501', dateName: '\uADFC\uB85C\uC790\uC758 \uB0A0' },
  { date: '1231', dateName: '\uCC3D\uB9BD\uAE30\uB150\uC77C\uB300\uD734' }
];

const baseline = $('Weekday Baseline').first().json;
const apiPayload = $('HTTP Request').first()?.json ?? {};
const dbPayload = $('Holiday DB Fallback').first()?.json ?? {};

function normalizeApiItems(raw) {
  if (!raw) return [];
  return Array.isArray(raw) ? raw : [raw];
}

const apiItems = !apiPayload.error
  ? normalizeApiItems(apiPayload.response?.body?.items?.item)
  : [];
const apiMatch = apiItems.find((item) => String(item?.locdate ?? '') === String(baseline.todayInt));
const customMatch = recurringHolidays.find((item) => item.date === baseline.todayMMDD);
const dbFound = !dbPayload.error && [true, 1, '1', 'true'].includes(dbPayload.found_in_db);

let isHoliday = !!baseline.DefaultIsHoliday;
let holidayName = baseline.DefaultHolidayName || (isHoliday ? '\uC8FC\uB9D0' : '\uD3C9\uC77C');
let holidayLookupSource = isHoliday ? 'default-weekend' : 'default-weekday';

if (apiMatch) {
  isHoliday = true;
  holidayName = String(apiMatch.dateName || '\uACF5\uD734\uC77C');
  holidayLookupSource = 'api';
} else if (customMatch) {
  isHoliday = true;
  holidayName = customMatch.dateName;
  holidayLookupSource = 'custom';
} else if (dbFound) {
  isHoliday = true;
  holidayName = String(dbPayload.holiday_name || '\uACF5\uD734\uC77C');
  holidayLookupSource = dbPayload.source_type ? `db:${dbPayload.source_type}` : 'db';
}

return [{
  json: {
    check_date: baseline.todayInt,
    is_holiday: isHoliday,
    holiday_name: holidayName,
    is_weekend: !!baseline.IsWeekend,
    weekday_name: baseline.WeekdayName,
    holiday_lookup_source: holidayLookupSource,
    holiday_lookup_failed: Boolean(apiPayload.error) && Boolean(dbPayload.error),
    api_error: apiPayload.error?.message || apiPayload.error || '',
    db_error: dbPayload.error || ''
  }
}];

const targetSubject = '기술지원파트 주간회의';
const response = $input.first().json;
const events = Array.isArray(response.value) ? response.value : [];

const matched = events.find((event) => {
  const subject = (event.subject ?? '').toString().trim();
  return subject === targetSubject;
});

if (!matched) {
  return [];
}

const startDateTime = matched.start?.dateTime ?? '';
const endDateTime = matched.end?.dateTime ?? '';
const start = startDateTime ? new Date(startDateTime) : null;
const end = endDateTime ? new Date(endDateTime) : null;

const dateText = start
  ? new Intl.DateTimeFormat('ko-KR', {
      timeZone: 'Asia/Seoul',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'short'
    }).format(start)
  : '';

const timeText = start && end
  ? `${new Intl.DateTimeFormat('ko-KR', {
      timeZone: 'Asia/Seoul',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(start)} ~ ${new Intl.DateTimeFormat('ko-KR', {
      timeZone: 'Asia/Seoul',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(end)}`
  : '';

return [{
  json: {
    meetingTitle: matched.subject ?? targetSubject,
    meetingStart: startDateTime,
    meetingEnd: endDateTime,
    meetingDateText: dateText,
    meetingTimeText: timeText,
    meetingLocation: matched.location?.displayName ?? '',
    meetingWebLink: matched.webLink ?? '',
    meetingType: matched.type ?? '',
    rawEvent: matched
  }
}];

const meeting = $('오늘 주간회의 확인').first().json;
const vacationItems = $('기술지원캘린더').all();
const WEEKLY_MEETING_PAGE_URL = 'https://app.notion.com/p/vmssolutions/ae3617323a5945fda70db4c1d8c8086d?v=2decb99583098030b178000c5d32f6cc';
const SPRINT_PAGE_URL = 'https://app.notion.com/p/vmssolutions/Sprint-2decb995830980e7910cd3495f371466';

const now = new Date();
const todayKST = new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Asia/Seoul'
}).format(now);

const dateString = new Intl.DateTimeFormat('ko-KR', {
  timeZone: 'Asia/Seoul',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  weekday: 'short'
}).format(now);

const allUsers = [
  { name: '조현재', email: 'jyi30@vms-solutions.com' },
  { name: '김민영', email: 'mykim@vms-solutions.com' },
  { name: '김진욱', email: 'jwkim@vms-solutions.com' }
];

const cleanStr = (str) => (str ?? '').toString().normalize('NFC').trim();
const norm = (str) => cleanStr(str).replace(/\s+/g, '').toLowerCase();

function collectStrings(value, result = [], depth = 0) {
  if (depth > 10 || value == null) return result;

  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    result.push(String(value));
    return result;
  }

  if (Array.isArray(value)) {
    for (const v of value) collectStrings(v, result, depth + 1);
    return result;
  }

  if (typeof value === 'object') {
    for (const v of Object.values(value)) collectStrings(v, result, depth + 1);
  }

  return result;
}

function itemToSearchText(item) {
  return collectStrings(item?.json ?? item).join(' ');
}

function isVacationText(text) {
  const t = norm(text);
  return [
    '휴가',
    '연차',
    '반차',
    '오전반차',
    '오후반차',
    '공가',
    '휴일',
    '공휴일',
    '명절',
    '휴무',
    '안식월',
    'sabbatical',
    'leave',
    'vacation',
    'pto',
    'dayoff',
    'off'
  ].some((keyword) => t.includes(norm(keyword)));
}

function extractAllYmds(text) {
  return String(text ?? '').match(/\d{4}-\d{2}-\d{2}/g) || [];
}

function extractYmd(str) {
  const m = String(str ?? '').match(/\d{4}-\d{2}-\d{2}/);
  return m ? m[0] : '';
}

function extractDateRanges(item) {
  const obj = item?.json ?? item;
  const ranges = [];
  const seen = new Set();

  function pushRange(key, start, end) {
    const s = extractYmd(start);
    const e = extractYmd(end || start);
    if (!s) return;

    const uniq = `${key}|${s}|${e}`;
    if (seen.has(uniq)) return;
    seen.add(uniq);

    ranges.push({ key, start: s, end: e || s });
  }

  function walk(value, path = 'root', depth = 0) {
    if (depth > 8 || value == null) return;

    if (typeof value === 'string') {
      const ymds = extractAllYmds(value);
      if (ymds.length === 1) pushRange(path, ymds[0], ymds[0]);
      else if (ymds.length >= 2) pushRange(path, ymds[0], ymds[1]);
      return;
    }

    if (typeof value === 'number' || typeof value === 'boolean') return;

    if (Array.isArray(value)) {
      value.forEach((v, idx) => walk(v, `${path}[${idx}]`, depth + 1));
      return;
    }

    if (typeof value === 'object') {
      if ('start' in value && extractYmd(value.start)) {
        pushRange(`${path}.startEnd`, value.start, value.end || value.start);
      }

      if ('date' in value && value.date && typeof value.date === 'object' && extractYmd(value.date.start)) {
        pushRange(`${path}.date`, value.date.start, value.date.end || value.date.start);
      }

      if (
        'formula' in value &&
        value.formula &&
        typeof value.formula === 'object' &&
        value.formula.type === 'date' &&
        value.formula.date &&
        extractYmd(value.formula.date.start)
      ) {
        pushRange(`${path}.formula.date`, value.formula.date.start, value.formula.date.end || value.formula.date.start);
      }

      for (const [k, v] of Object.entries(value)) {
        walk(v, `${path}.${k}`, depth + 1);
      }
    }
  }

  walk(obj);
  return ranges;
}

function isTodayIncluded(start, end, today) {
  if (!start) return false;
  const realEnd = end || start;
  return start <= today && today <= realEnd;
}

const todayVacationItems = vacationItems.filter((item) => {
  const text = itemToSearchText(item);
  if (!isVacationText(text)) return false;

  const ranges = extractDateRanges(item);
  if (ranges.length === 0) return false;

  return ranges.some((r) => isTodayIncluded(r.start, r.end, todayKST));
});

const vacationUsers = allUsers.filter((user) => {
  return todayVacationItems.some((item) => {
    const text = itemToSearchText(item);
    return norm(text).includes(norm(user.name)) || norm(text).includes(norm(user.email));
  });
});

const vacationUserEmails = new Set(vacationUsers.map((u) => u.email));
const activeUsers = allUsers.filter((u) => !vacationUserEmails.has(u.email));

let teamsText = '지원 담당자';
let teamsEntities = [];

if (activeUsers.length > 0) {
  teamsText = activeUsers.map((u) => `<at>${u.name}</at>`).join(', ');
  teamsEntities = activeUsers.map((u) => ({
    type: 'mention',
    text: `<at>${u.name}</at>`,
    mentioned: { id: u.email, name: u.name }
  }));
}

const vacationText = vacationUsers.length > 0
  ? vacationUsers.map((u) => u.name).join(', ')
  : '없음';

return [{
  json: {
    teamsText,
    teamsEntities,
    date: dateString,
    meetingTitle: meeting.meetingTitle,
    meetingDateText: meeting.meetingDateText,
    meetingTimeText: meeting.meetingTimeText,
    meetingLocation: meeting.meetingLocation || '미지정',
    meetingWebLink: meeting.meetingWebLink || '',
    weeklyMeetingPageUrl: WEEKLY_MEETING_PAGE_URL,
    sprintPageUrl: SPRINT_PAGE_URL,
    weeklyMeetingLinksMarkdown: `Weekly Meeting: [Open](${WEEKLY_MEETING_PAGE_URL})\nSprint: [Open](${SPRINT_PAGE_URL})`,
    activeUserCount: activeUsers.length,
    activeUsersText: activeUsers.length > 0 ? activeUsers.map((u) => u.name).join(', ') : '없음',
    vacationUsersText: vacationText,
    messageSummary: `${meeting.meetingDateText} ${meeting.meetingTimeText}`.trim()
  }
}];

